-- Node: frostbite-grade2 (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Grade 2: Consider Iloprost","body":"**tPA is not indicated at this depth.** The guideline reserves thrombolysis for injury reaching the proximal interphalangeal joint or beyond.\n\n**Iloprost at grade 2 is an expert extension, not proven.** The WMS 2024 update suggests [iloprost](#/drug/iloprost/frostbite) may be considered for deep injury short of the PIP joint, within 72 h of injury. The FDA approval and its trial covered only stage 3 and 4 injuries, so benefit at grade 2 is extrapolated; decide with a frostbite-experienced specialist.\n\nSee [Iloprost](#/node/frostbite-iloprost) for dosing, then [Wound care](#/node/frostbite-wound). [1][2][3]","citation":[1,2,3],"recommendation":"Cauchy grade 2 frostbite: thrombolysis is not indicated. IV iloprost may be considered within 72 hours of injury after specialist discussion (expert extension; the FDA approval covers stage 3-4 only); supportive and wound care for all.","confidence":"consider","calculatorLinks":[{"id":"frostbite-iloprost-rate","label":"Iloprost Rate"}],"summary":"No tPA; iloprost only after specialist discussion (unproven at grade 2)"}'::jsonb
WHERE id = 'frostbite-grade2' AND tree_id = 'frostbite';

-- Node: frostbite-tpa (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Thrombolysis (tPA)","body":"**Start as soon as possible.** In a small retrospective series (73 patients), the odds of salvage fell about 28% for each hour of delay; earlier is better, though no trial defines a 12 h cutoff.\n\n**Regimen used in the WMS guideline:** [alteplase](#/drug/alteplase/frostbite) 3 mg bolus, then 1 mg/h, IV or intra-arterial, **with** [heparin](#/drug/ufh/frostbite) 500 units/h. Continue until specialists (vascular, burn, interventional radiology) say to stop. Follow local protocol.\n\n**Evidence:** in a small retrospective single-centre series (only 6 patients got intra-arterial tPA within 24 h), digital amputation fell from 41% without tPA to 10% with tPA.\n\n**Risks:** bleeding (systemic and at the catheter site), compartment syndrome, and failure to salvage. Watch the compartments after reperfusion.\n\nThen: [Wound care](#/node/frostbite-wound). [1][4][5]","citation":[1,4,5],"recommendation":"Deep frostbite at or proximal to the PIP joint within 24 hours of thaw and without contraindication: IV or intra-arterial tPA with concurrent heparin in a monitored setting, as early as possible.","confidence":"recommended","summary":"Alteplase 3 mg bolus then 1 mg/h + heparin 500 units/h in an ICU; sooner is better","safetyLevel":"critical"}'::jsonb
WHERE id = 'frostbite-tpa' AND tree_id = 'frostbite';

-- Node: frostbite-iloprost (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Iloprost (Prostacyclin)","body":"**[Iloprost](#/drug/iloprost/frostbite) (AURLUMYN)** is a prostacyclin (PGI2) analogue: it dilates vessels and stops platelets clumping. It is FDA approved (2024) for severe frostbite in adults to lower the risk of finger or toe amputation.\n\n**When:** grade 3 to 4 within 72 h of injury when tPA is contraindicated (an intracranial hemorrhage such as a subdural hematoma, active bleeding, major trauma), when it is past the tPA window, or when evacuation will be delayed.\n\n**Label dosing:** start 0.5 ng/kg/min IV and increase by 0.5 ng/kg/min every 30 min as tolerated, to a maximum of 2 ng/kg/min. Run for **6 hours a day, for up to 8 days**. **Repeat the titration from 0.5 on days 2 and 3**; from day 4, start at the highest dose tolerated the day before. Child-Pugh B or C: start at 0.25 ng/kg/min.\n\n**Watch for hypotension.** Correct it before starting and monitor vital signs. Headache, flushing, nausea and palpitations are common.\n\n**Evidence:** in the randomized trial behind the approval, a day-7 bone-scan defect (which predicts amputation) occurred in 0% with iloprost, 19% with iloprost plus tPA and 60% with buflomedil. **Every arm also got [aspirin](#/drug/aspirin/frostbite) 250 mg IV daily for up to 8 days**; consider aspirin alongside iloprost unless contraindicated (IV aspirin is not marketed in the US; agree an oral regimen with pharmacy).\n\nThen: [Wound care](#/node/frostbite-wound). [1][3][6]","citation":[1,3,6],"recommendation":"Severe frostbite (Cauchy grade 3-4) within 72 hours when thrombolysis is contraindicated or not feasible: IV iloprost per the FDA label, 0.5 ng/kg/min titrated to a maximum of 2 ng/kg/min, 6 hours daily for up to 8 days, with blood pressure monitoring.","confidence":"recommended","calculatorLinks":[{"id":"frostbite-iloprost-rate","label":"Iloprost Rate"}],"summary":"Iloprost 0.5 → max 2 ng/kg/min, 6 h/day up to 8 days; watch BP","safetyLevel":"warning"}'::jsonb
WHERE id = 'frostbite-iloprost' AND tree_id = 'frostbite';

-- Node: hemolytic-anemia-danger (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Danger Screen","body":"Before working out the cause, rule out the emergencies.\n\n**Ask about drugs:** quinine, clopidogrel or ticlopidine, gemcitabine, calcineurin inhibitors (drug-induced TMA); recent ceftriaxone, piperacillin or other antibiotics (drug-induced immune hemolysis, which can be abrupt and severe). Stop the suspect drug. [4][14]","citation":[4,14],"options":[{"label":"Schistocytes with low platelets","description":"Microangiopathic hemolysis (MAHA): TTP, HUS, drug-induced TMA, DIC, HELLP, malignant hypertension","next":"hemolytic-anemia-tma","urgency":"critical"},{"label":"Started during or after a transfusion","description":"Fever, back pain, red urine, hypotension, or hemoglobin falling 3-14 days after transfusion","next":"hemolytic-anemia-transfusion-rxn","urgency":"critical"},{"label":"None of these","description":"Go to DAT and smear","next":"hemolytic-anemia-dat"}],"summary":"TMA and transfusion reactions first"}'::jsonb
WHERE id = 'hemolytic-anemia-danger' AND tree_id = 'hemolytic-anemia';

-- Node: hemolytic-anemia-tma (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Microangiopathic Hemolysis (TMA)","body":"**Schistocytes + thrombocytopenia + hemolysis = thrombotic microangiopathy** until proven otherwise. Untreated TTP is often fatal, so do not wait for ADAMTS13.\n\n• Check the [PLASMIC score](#/calculator/ttp-plasmic), coagulation tests (DIC), creatinine, pregnancy status and blood pressure.\n• **High PLASMIC: urgent hematology for plasma exchange.** Open the [TTP consult](#/tree/ttp).\n• **Bloody diarrhea, especially in a child: STEC-HUS.** Avoid antibiotics and antimotility drugs (loperamide) in suspected Shiga toxin E. coli (O157) infection: antibiotics are linked to a higher risk of HUS. Fluids, monitor creatinine and platelets. [13][15]\n• **Drug-induced TMA:** quinine, clopidogrel or ticlopidine, gemcitabine, calcineurin inhibitors. Stop the drug. [14]\n• **Avoid platelet transfusion in suspected TTP** unless there is life-threatening bleeding. [12]","citation":[1,3,12,13,14,15],"recommendation":"Schistocytes with thrombocytopenia: treat as TMA. Calculate PLASMIC and involve hematology urgently for plasma exchange if TTP is likely; avoid platelet transfusion unless life-threatening bleeding. In suspected STEC-HUS avoid antibiotics and antimotility drugs; stop any drug that can cause TMA.","confidence":"recommended","images":[{"src":"images/hemolytic-anemia/schistocytes-smear.jpg","alt":"Peripheral blood smear: mostly round red cells with pale centres, plus several small fragmented and helmet-shaped red cells (schistocytes) scattered among them.","caption":"Schistocytes (fragmented red cells) among normal cells; cropped. (CC0, Prof. Osaro Erhabor, via Wikimedia Commons.)"}],"calculatorLinks":[{"id":"ttp-plasmic","label":"PLASMIC Score"},{"id":"ttp-tma-ddx","label":"TMA Differential"},{"id":"ttp","label":"TTP Consult","kind":"tree"}],"summary":"TMA: PLASMIC, urgent hematology, plasma exchange; no platelets in TTP","safetyLevel":"critical"}'::jsonb
WHERE id = 'hemolytic-anemia-tma' AND tree_id = 'hemolytic-anemia';

-- Node: hemolytic-anemia-warm-tx (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Warm AIHA: Treatment","body":"**First line:** [Prednisone](#/drug/prednisone/warm autoimmune hemolytic anemia) **1 mg/kg/day PO**. Expect a response within about 3 weeks; hematology then tapers slowly over months. [1][6]\n\n**Severe or rapidly falling hemoglobin:**\n• [Methylprednisolone](#/drug/methylprednisolone/warm autoimmune hemolytic anemia) IV for fulminant cases (evidence limited to case reports).\n• [IVIG](#/drug/ivig/warm autoimmune hemolytic anemia) as a temporary rescue (about 40% respond, usually briefly).\n• Consider adding [rituximab](#/drug/rituximab-ttp/warm autoimmune hemolytic anemia) early with the steroid. [1][6][7]\n\n**For everyone:**\n• [Folic acid](#/drug/folic-acid/hemolytic anemia) supplementation.\n• **Consider VTE prophylaxis** with [enoxaparin](#/drug/enoxaparin/vte prophylaxis) for in-patients, per hematology and standard VTE risk assessment: clots occur more often during active hemolysis, but the evidence is observational.\n• Stop any suspect drug. [1]\n\n**Transfusion:** do not withhold blood from a patient with life-threatening anemia because the crossmatch is \"incompatible\". See [Transfusion](#/node/hemolytic-anemia-transfusion).","citation":[1,6,7],"recommendation":"Warm AIHA: prednisone 1 mg/kg/day; for severe disease add IVIG as a temporary rescue and consider early rituximab with hematology. Give folic acid, and consider LMWH prophylaxis for in-patients per VTE risk.","confidence":"recommended","summary":"Prednisone 1 mg/kg/day; rituximab early if severe; folic acid and LMWH"}'::jsonb
WHERE id = 'hemolytic-anemia-warm-tx' AND tree_id = 'hemolytic-anemia';

-- Node: hemolytic-anemia-transfusion (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Transfusion in Hemolysis","body":"**Thresholds:** hemoglobin under 7 g/dL for most stable patients, under 8 g/dL with heart disease. [11] Symptoms (chest pain, syncope, heart failure, a rapid fall) may justify transfusion above these numbers: clinical judgment.\n\n**Autoimmune hemolysis:** the autoantibody makes every crossmatch look \"incompatible\", and full workup can take 4-6 hours. **If anemia is life-threatening in that time, transfuse ABO, Rh and K matched red cells; do not withhold blood.** Call the blood bank early and tell them the diagnosis. Most patients tolerate these units. [1]\n\n**Cold agglutinin disease:** use a **blood warmer** and keep the patient warm. [1]\n\nGive small volumes (1 unit at a time) and recheck: [packed red cells](#/drug/packed-rbcs/adult transfusion).","citation":[1,11],"next":"hemolytic-anemia-dispo","recommendation":"In AIHA with life-threatening anemia, do not delay transfusion for full compatibility testing: give ABO, Rh and K matched red cells, and use a blood warmer in cold agglutinin disease.","confidence":"recommended","calculatorLinks":[{"id":"blood-transfusions","label":"AIHA Transfusion","kind":"tree","node":"bt-aiha"}],"summary":"Hb <7 (or <8 cardiac) or symptoms; never withhold blood in AIHA","safetyLevel":"warning"}'::jsonb
WHERE id = 'hemolytic-anemia-transfusion' AND tree_id = 'hemolytic-anemia';

